sys_script_include.script:
var AppReadyAssignmentService = Class.create();
AppReadyAssignmentService.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    initialize: function() {},

    assignUser: function() {
        var applicationId = this.getParameter('sysparm_application_id');
        var userId = this.getParameter('sysparm_user_id');
        var roleType = this.getParameter('sysparm_role_type');

        var existing = new GlideRecord('x_1433041_identi_0_assignment');
        existing.addQuery('application', applicationId);
        existing.addQuery('role', roleType);
        existing.addQuery('active', true);
        existing.query();
        while (existing.next()) {
            existing.setValue('active', false);
            existing.update();
        }

        var gr = new GlideRecord('x_1433041_identi_0_assignment');
        gr.initialize();
        gr.setValue('application', applicationId);
        gr.setValue('user', userId);
        gr.setValue('role', roleType);
        gr.setValue('active', true);
        gr.setValue('assigned_at', new GlideDateTime().getDisplayValue());
        gr.setValue('assigned_by', gs.getUserID());
        var assignmentId = gr.insert();

        if (roleType === 'application_owner') {
            var appGr = new GlideRecord('x_1433041_identi_0_application');
            if (appGr.get(applicationId)) {
                appGr.setValue('assigned_owner', userId);
                appGr.update();
            }
        }

        this._logAudit(applicationId, 'assignment_created', 'User assigned as ' + roleType);

        return JSON.stringify({ success: true, assignment_id: assignmentId });
    },

    removeAssignment: function() {
        var assignmentId = this.getParameter('sysparm_assignment_id');
        var gr = new GlideRecord('x_1433041_identi_0_assignment');
        if (!gr.get(assignmentId)) {
            return JSON.stringify({ success: false, message: 'Assignment not found' });
        }
        gr.setValue('active', false);
        gr.update();
        return JSON.stringify({ success: true, message: 'Assignment deactivated' });
    },

    getAssignments: function() {
        var applicationId = this.getParameter('sysparm_application_id');
        var assignments = [];
        var gr = new GlideRecord('x_1433041_identi_0_assignment');
        gr.addQuery('application', applicationId);
        gr.addQuery('active', true);
        gr.query();
        while (gr.next()) {
            var userGr = new GlideRecord('sys_user');
            var userName = '';
            var userEmail = '';
            if (userGr.get(gr.getValue('user'))) {
                userName = userGr.getValue('name');
                userEmail = userGr.getValue('email');
            }
            assignments.push({
                sys_id: gr.getUniqueValue(),
                role: gr.getValue('role'),
                user_id: gr.getValue('user'),
                user_name: userName,
                user_email: userEmail,
                assigned_at: gr.getValue('assigned_at'),
                assigned_by: gr.getValue('assigned_by')
            });
        }
        return JSON.stringify({ success: true, assignments: assignments });
    },

    resolveRecipient: function() {
        var applicationId = this.getParameter('sysparm_application_id');
        var roleType = this.getParameter('sysparm_role_type');
        var gr = new GlideRecord('x_1433041_identi_0_assignment');
        gr.addQuery('application', applicationId);
        gr.addQuery('role', roleType);
        gr.addQuery('active', true);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) {
            return JSON.stringify({ success: true, user_id: gr.getValue('user') });
        }
        return JSON.stringify({ success: false, message: 'No active assignment found for role: ' + roleType });
    },

    resolveRecipientByStatus: function() {
        var applicationId = this.getParameter('sysparm_application_id');
        var appGr = new GlideRecord('x_1433041_identi_0_application');
        if (!appGr.get(applicationId)) {
            return JSON.stringify({ success: false, message: 'Application not found' });
        }

        var status = appGr.getValue('questionnaire_status');
        var roleType = 'application_owner';

        if (status === 'in_progress' || status === 'draft') {
            roleType = 'application_owner';
        } else if (status === 'clarification_requested') {
            roleType = 'application_owner';
        } else if (status === 'admin_review') {
            roleType = 'program_manager';
        }

        var gr = new GlideRecord('x_1433041_identi_0_assignment');
        gr.addQuery('application', applicationId);
        gr.addQuery('role', roleType);
        gr.addQuery('active', true);
        gr.setLimit(1);
        gr.query();
        if (gr.next()) {
            return JSON.stringify({ success: true, user_id: gr.getValue('user'), resolved_role: roleType });
        }
        return JSON.stringify({ success: false, message: 'No active assignment found' });
    },

    _logAudit: function(applicationId, eventType, description) {
        var auditGr = new GlideRecord('x_1433041_identi_0_audit_event');
        auditGr.initialize();
        auditGr.setValue('application', applicationId);
        auditGr.setValue('event_type', eventType);
        auditGr.setValue('description', description);
        auditGr.setValue('performed_by', gs.getUserID());
        auditGr.setValue('performed_at', new GlideDateTime().getDisplayValue());
        auditGr.setValue('target_table', 'x_1433041_identi_0_assignment');
        auditGr.setValue('target_record', applicationId);
        auditGr.insert();
    },

    type: 'AppReadyAssignmentService'
});
